inline void rememberModelPreferences(json& cfg,const std::string& name="") {json identity=cfg;if(!name.empty())identity["workflow_profile"]=name;auto key=modelId(identity);json values=json::object();for(auto& k:modelPreferenceKeys)if(cfg.contains(k))values[k]=cfg[k];if(!cfg.contains("_model_settings")||!cfg["_model_settings"].is_object())cfg["_model_settings"]=json::object();cfg["_model_settings"][key]=values;}
inline void restoreModelPreferences(json& cfg,const fs::path& root,const std::string& previous){rememberModelPreferences(cfg,previous);auto base=defaults(root);auto cache=cfg.value("_model_settings",json::object());auto key=modelId(cfg);for(auto& k:modelPreferenceKeys){cfg.erase(k);if(base.contains(k))cfg[k]=base[k];}cfg.erase("_pixel_active");cfg.erase("_before_pixel");cfg.erase("_before_pixel_model");if(cache.contains(key))cfg.update(cache[key]);else {if(key=="pixel_art"){cfg["width"]="1024";cfg["height"]="1024";cfg["pixel_width"]="128";cfg["pixel_height"]="128";}applyModelSettings(cfg,true);}if(key.find("flux2")==0){cfg["quality_tags"]=false;cfg["enhance"]=false;cfg["use_default_negative"]=false;for(auto k:{"width","height"})cfg[k]=std::to_string((std::stoi(str(cfg,k))+15)/16*16);}applyModelSettings(cfg);rememberModelPreferences(cfg);}
