class Store {
public:
 fs::path root,baseRoot;bool workspaceBound=false;std::string workspaceScope;json doc,settings,state;std::string active,lastDoc,lastState,lastSettings;std::mutex mutex;
 explicit Store(fs::path data):root(data),baseRoot(std::move(data)){}
 void useWorkspace(const std::string& scope){if(!scope.empty()&&(scope.size()!=64||scope.find_first_not_of("0123456789abcdef")!=std::string::npos))throw std::runtime_error("계정 작업 공간 식별자가 올바르지 않습니다.");if(workspaceBound&&workspaceScope==scope)return;json shared=json::object();for(auto key:{"api","auto_update","splash_minimum_enabled"})if(settings.contains(key))shared[key]=settings[key];if(workspaceBound)save();root=baseRoot/"local_accounts"/(scope.empty()?"signed-out":scope.substr(0,32));if(!scope.empty()){auto binding=root/"account-scope.json";if(fs::exists(binding)){if(str(readJson(binding),"scope")!=scope)throw std::runtime_error("계정 작업 공간 식별값이 일치하지 않습니다.");}else{if(fs::exists(root/"config/channels.json"))throw std::runtime_error("계정 식별 정보가 없는 작업 공간은 자동으로 불러올 수 없습니다.");atomicWrite(binding,json{{"scope",scope}}.dump());}}workspaceScope=scope;workspaceBound=true;doc=json::object();state=json::object();settings=json::object();active.clear();lastDoc.clear();lastState.clear();lastSettings.clear();load();settings.update(shared);settings["api_key"]="";settings["content_mode"]="standard";settings["_local_workspace_root"]=utf8(root.wstring());settings["_local_account_scope"]=scope;save();}
 void loadBootstrap(){settings=defaults(baseRoot);auto file=baseRoot/"config/canvas_settings.json";if(fs::exists(file)){auto legacy=readJson(file);for(auto key:{"api","auto_update","splash_minimum_enabled"})if(legacy.contains(key))settings[key]=legacy[key];}useWorkspace("");}
 void load(){fs::create_directories(root/"config");fs::create_directories(root/"prompts");fs::create_directories(root/"generated");settings=defaults(root);
  if(fs::exists(root/"config/canvas_settings.json"))settings.update(readJson(root/"config/canvas_settings.json"));
  if(str(settings,"api").empty())settings["api"]="http://1.240.182.65:8000";
  if(fs::exists(root/"config/credentials.json")&&str(settings,"api_key").empty())settings["api_key"]=readJson(root/"config/credentials.json").value("default_api_key","");
  fs::path channels=root/"config/channels.json";if(fs::exists(channels)){doc=readJson(channels);if(!doc.contains("channels")||!doc["channels"].is_array()||doc["channels"].empty())throw std::runtime_error("프로젝트 목록 형식 오류. 기존 파일은 보존했습니다.");active=doc.value("active","");bool found=false;for(auto& c:doc["channels"])if(str(c,"id")==active)found=true;if(!found)active=str(doc["channels"][0],"id");state=current()["state"];}
  else {state=fs::exists(root/"config/canvas_session.json")?readJson(root/"config/canvas_session.json"):newState(settings);if(fs::exists(root/"prompts/prompt.txt"))state["drafts"]["prompt"]=readFile(root/"prompts/prompt.txt");if(fs::exists(root/"prompts/negative.txt"))state["negative"]=readFile(root/"prompts/negative.txt");active=id();doc={{"version",1},{"active",active},{"channels",json::array({{{"id",active},{"name","기존 작업"},{"pinned",true},{"state",state}}})}};}
  prepareProjectOrganizer(doc);restore();
 }
 json& current(){for(auto& c:doc["channels"])if(str(c,"id")==active)return c;throw std::runtime_error("현재 프로젝트를 찾을 수 없습니다.");}
 void restore(){auto base=defaults(root);base.update(state.value("settings",json::object()));for(auto& key:globalKeys)base[key]=settings.contains(key)?settings[key]:defaults(root)[key];settings=base;state["settings"]=settings;for(auto& key:globalKeys)state["settings"].erase(key);if(!state.contains("drafts"))state["drafts"]=state["project"].value("prompt_sections",json::object());if(!state.contains("negative"))state["negative"]=state["project"].value("negative","");}
 void snapshot(){rememberModelPreferences(settings);state["settings"]=settings;for(auto& key:globalKeys)state["settings"].erase(key);state["project"]["prompt_sections"]=state["drafts"];state["project"]["negative"]=state["negative"];state["project"]["enhance"]=flag(settings,"enhance");state["project"]["use_default_negative"]=flag(settings,"use_default_negative");current()["state"]=state;doc["active"]=active;}
 void save(){std::lock_guard lock(mutex);snapshot();for(auto& channel:doc["channels"])for(auto& key:globalKeys)channel["state"]["settings"].erase(key);auto d=doc.dump(2),s=state.dump(2),c=settings.dump(2);if(d!=lastDoc){atomicWrite(root/"config/channels.json",d);lastDoc=d;}if(s!=lastState){atomicWrite(root/"config/canvas_session.json",s);lastState=s;}if(c!=lastSettings){atomicWrite(root/"config/canvas_settings.json",c);lastSettings=c;}}
 void switchTo(const std::string& next){snapshot();active=next;state=current()["state"];restore();save();}
 void create(const std::string& name,bool copy=false){snapshot();auto folder=projectFolder(doc,current());auto fresh=copy?state:newState(defaults(root));auto key=id();fresh["settings"]["output"]=utf8((root/"generated"/key).wstring());fresh["selected"]=nullptr;doc["channels"].push_back({{"id",key},{"name",name},{"pinned",false},{"folder_id",folder},{"state",fresh}});switchTo(key);}
 void resetSettings(){auto fresh=defaults(root);for(auto& key:globalKeys)fresh[key]=settings[key];fresh["output"]=settings.value("output",fresh["output"]);settings=std::move(fresh);state["settings"]=settings;save();}
 void patchProject(const std::string& project,const json& patch){std::lock_guard lock(mutex);snapshot();for(auto& c:doc["channels"])if(str(c,"id")==project){for(auto it=patch.begin();it!=patch.end();++it)c["state"]["settings"][it.key()]=it.value();if(project==active){settings.update(patch);state["settings"]=settings;}break;}atomicWrite(root/"config/channels.json",doc.dump(2));}
};
inline json controls(const json& cfg){json out=json::object();if(modelId(cfg)=="pixel_art"){int pw=std::stoi(str(cfg,"pixel_width","128")),ph=std::stoi(str(cfg,"pixel_height","128"));if(pw<16||pw>256||ph<16||ph>256||float(pw)/ph<.5f||float(pw)/ph>2.f)throw std::runtime_error("픽셀 해상도: 16~256, 가로세로 비율 1:2~2:1 범위로 선택하세요.");out["pixel_width"]=pw;out["pixel_height"]=ph;}std::set<std::string> ints={"steps","hires_steps","tile_size","tile_overlap","clip_skip"},floats={"cfg","denoise","lora_strength","lora_clip_strength","hires_scale","hires_cfg","hires_denoise"};std::set<std::string> strings={"sampler","scheduler","checkpoint","vae","lora","upscale_model","diffusion_model","text_encoder","hires_sampler","hires_scheduler"};
 for(auto& key:ints){auto value=str(cfg,key);if(value=="Steps와 동일")value=str(cfg,"steps");if(value.empty()||value=="서버 기본")continue;size_t end=0;long long n=std::stoll(value,&end);if(end!=value.size())throw std::runtime_error("정수 입력 오류: "+key);out[key]=n;}
 for(auto& key:floats){auto value=str(cfg,key);if(value.empty())continue;size_t end=0;double n=std::stod(value,&end);if(end!=value.size()||!std::isfinite(n))throw std::runtime_error("숫자 입력 오류: "+key);out[key]=n;}
 for(auto& key:strings){auto value=str(cfg,key);if(!value.empty()&&value!="서버 기본"&&value!="사용 안 함"&&value!="기본과 동일")out[key]=value;}
 auto mode=str(cfg,"hires_mode");if(mode=="확대만")out["hires_mode"]="upscale";
 auto enabled=str(cfg,"hires_enabled");if(enabled!="서버 기본")out["hires_enabled"]=enabled=="켜기";
 std::map<std::string,std::string> pipeline={{"픽셀아트","pixel_art"},{"픽셀아트 · 8× 격자","pixel_art"},{"기존 SDXL","sdxl"},{"애니 · Illustrious XL","illustrious"},{"문장·실사 · FLUX 빠르게","flux2_klein"},{"문장·실사 · FLUX 고품질","flux2_klein_base"}};
 auto p=pipeline.find(str(cfg,"workflow_profile"));if(p==pipeline.end())throw std::runtime_error("생성 모델 오류");if(p->second!="sdxl")out["pipeline"]=p->second;
 auto overrides=json::parse(str(cfg,"node_overrides","{}"));if(!overrides.is_object())throw std::runtime_error("노드 JSON은 객체여야 합니다.");if(!overrides.empty())out["node_overrides"]=overrides;
 auto number=[&](const char* k,double minimum,double maximum){if(out.contains(k)){double v=out[k];if(v<minimum||v>maximum)throw std::runtime_error(std::string("범위 오류: ")+k);}};
 number("steps",1,1e12);number("hires_steps",0,1e12);number("cfg",0,1e12);number("denoise",0,1);number("hires_denoise",0,1);number("hires_scale",1,1e12);number("clip_skip",-24,-1);number("tile_size",64,1e12);number("tile_overlap",0,1e12);number("lora_strength",-10,10);number("lora_clip_strength",-10,10);
 if(out.value("tile_overlap",64)>=out.value("tile_size",512))throw std::runtime_error("타일 겹침은 타일 크기보다 작아야 합니다.");return guardModelControls(cfg,out);}
inline void validate(const json& cfg){auto prefix=str(cfg,"version");if(prefix.empty()||prefix.find_first_of("/\\:*?\"<>|\r\n")!=std::string::npos)throw std::runtime_error("파일 접두사를 확인하세요.");int width=std::stoi(str(cfg,"width")),height=std::stoi(str(cfg,"height")),count=std::stoi(str(cfg,"count"));int multiple=str(cfg,"workflow_profile").find("FLUX")!=std::string::npos?16:8;if(width<=0||height<=0||width%multiple||height%multiple)throw std::runtime_error("너비·높이는 양수이며 "+std::to_string(multiple)+"의 배수여야 합니다.");if(count<1)throw std::runtime_error("생성 장수는 1 이상이어야 합니다.");auto seed=std::stoll(str(cfg,"seed"));if(seed< -1)throw std::runtime_error("시드 범위 오류");controls(cfg);}
